                elif r%2==1: put(pat,'chat',row,note='D-5',vol=18)
                elif r not in (0,4,8,12): put(pat,'chat',row,note='D-5',vol=26)
            elif style=='sparse':
                if r in (2,6,10,14): put(pat,'chat',row,note='D-5',vol=16)

