    for r in rows: put(pat,'ohat',r,note='D-5',vol=vol)

def bass_pump(pat, chords, vel=50, acc=True):
    for b,c in enumerate(chords):
        r = c['root']  # this root placed in octave ~ 'root octave' param given to chord()
        br = c['root'] - 12*2   # drop 2 octaves -> octave 2 zone
        patt = [(0,br,58 if acc else vel),(2,br,vel),(4,br+12,vel-4),(6,br,vel),
                (8,br,48 if acc else vel),(10,br+12,vel-4),(12,br,vel),(14,br+7,vel-2)]
        for dr,n,v in patt:
            put(pat,'bass',b*16+dr,note=n,vol=v)

def arp(pat, chords, vol=28, half=False, order=(0,'t3','t5',12)):
    for b,c in enumerate(chords):
        step = 2 if half else 1
        seq = [c['root'], c['root']+c['t3'], c['root']+c['t5'], c['root']+12]
        k=0
        for r in range(0,16,step):
            n = seq[k%4]
            put(pat,'arp',b*16+r,note=n,vol=vol if k%2==0 else vol-6)
            k+=1

def stab(pat, rows, chords, vol=30):
    # rows given as (bar,row-in-bar); stab = root+12+fifth
    for b,dr in rows:
        c = chords[b]
        put(pat,'stab',b*16+dr,note=c['root']+c['t5']+12,vol=vol)

# ---------------- patterns ----------------
# P0 intro — chords MAJ
kick_rows(0)
snare_backbeat(0)  # only want bars 3-4 -> overwrite: clear bars 1-2 by redoing manually
